package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class FastMath_signum_TriageGen1Test {







    @Test
    public void testSignumNaN() {
        double result = FastMath.signum(Double.NaN);
        assertEquals(Double.NaN, result, 0.0);
        // Note: assertEquals(expected, actual, delta) with NaN requires special handling 
        // or checking isNaN, but for JUnit 4 with delta, if both are NaN, it might fail.
        // However, standard behavior for signum(NaN) is NaN.
        if (!Double.isNaN(result)) {
            throw new AssertionError("Expected NaN");
        }
    }


}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class FastMath_signum_TriageGen1Test {









    @Test
    public void testSignumEdgeCases() {
        // Testing positive infinity
        assertEquals(1.0, FastMath.signum(Double.POSITIVE_INFINITY), 0.0);
        // Testing negative infinity
        assertEquals(-1.0, FastMath.signum(Double.NEGATIVE_INFINITY), 0.0);
    }
}
